@php
    $chartMetrics = collect($data['insights'] ?? [])->map(fn ($metric) => ['name' => $metric['title'] ?? str($metric['name'] ?? 'Metric')->replace('_', ' ')->title()->toString(), 'labels' => collect($metric['values'] ?? [])->map(fn ($value) => \Illuminate\Support\Carbon::parse($value['end_time'] ?? now())->format('M d'))->all(), 'values' => collect($metric['values'] ?? [])->map(fn ($value) => is_numeric($value['value'] ?? null) ? (float) $value['value'] : null)->all()])->filter(fn ($metric) => count($metric['values']) > 0 && (count($metric['values']) > 1 || $since === $until))->values();
    $viewKeys = $platform === 'instagram' ? ['views', 'video_views'] : ['post_media_view', 'post_video_views'];
    $followerName = $platform === 'instagram' ? 'follower_count' : 'page_follows';
    $followerMetric = collect($data['insights'] ?? [])->firstWhere('name', $followerName);
    $followerPoints = collect($followerMetric['values'] ?? [])->filter(fn ($point) => is_numeric($point['value'] ?? null))->sortBy('end_time')->values();
    $followerValue = $followerPoints->count() > 1 ? (float) $followerPoints->last()['value'] - (float) $followerPoints->first()['value'] : null;
    $previousFollowerMetric = collect($previous['insights'] ?? [])->firstWhere('name', $followerName);
    $previousFollowerPoints = collect($previousFollowerMetric['values'] ?? [])->filter(fn ($point) => is_numeric($point['value'] ?? null))->sortBy('end_time')->values();
    $previousFollowerValue = $previousFollowerPoints->count() > 1 ? (float) $previousFollowerPoints->last()['value'] - (float) $previousFollowerPoints->first()['value'] : null;
    $overviewMetrics = collect($data['insights'] ?? [])->filter(fn ($metric) => ($metric['name'] ?? '') !== 'follower_count')->map(function ($metric) {
        $points = collect($metric['values'] ?? [])->filter(fn ($point) => is_numeric($point['value'] ?? null))->values();
        $name = $metric['name'] ?? '';
        $latestValue = in_array($name, ['reach', 'page_follows'], true);
        $label = $name === 'reach' ? 'Latest daily reach' : ($name === 'page_follows' ? 'Page followers' : ($metric['title'] ?? str($name)->replace('_', ' ')->title()->toString()));
        $value = $latestValue ? $points->last()['value'] ?? null : ($points->isEmpty() ? data_get($metric, 'total_value.value') : $points->sum('value'));
        return ['label' => $label, 'value' => $value];
    })->values();
