@forelse($data['media'] as $item)@php($views = collect($viewKeys)->first(fn ($key) => isset($item['metrics'][$key])))@php($likes = $item['metrics']['likes'] ?? $item['metrics']['reactions'] ?? null)@php($reach = $item['metrics']['reach'] ?? $item['metrics']['post_impressions_unique'] ?? null)@php($interactionValues = collect([$likes, $item['metrics']['comments'] ?? null, $item['metrics']['shares'] ?? null, $item['metrics']['saved'] ?? null])->filter(fn ($value) => is_numeric($value)))@php($engagement = $interactionValues->isNotEmpty() ? $interactionValues->sum() : null)@php($engagementRate = is_numeric($engagement) && is_numeric($reach) && $reach > 0 ? ($engagement / $reach) * 100 : null)<tr data-kind="{{ $item['type'] ?? '' }}"><td>{{ !empty($item['published_at']) ? \Illuminate\Support\Carbon::parse($item['published_at'])->timezone(auth()->user()->timezone ?: config('app.timezone'))->format('M d, Y h:i A') : '—' }}</td><td class="analytics-content">@if(!empty($item['thumbnail']))<img class="analytics-thumb" src="{{ $item['thumbnail'] }}" alt="" loading="lazy">@endif{{ \Illuminate\Support\Str::limit($item['text'] ?? 'Untitled post', 90) }} @if(!empty($item['url']))<a href="{{ $item['url'] }}" target="_blank" rel="noopener">Open</a>@endif</td><td><span class="badge text-bg-light">{{ $item['type'] ?? '—' }}</span></td><td>{{ $views && is_numeric($item['metrics'][$views] ?? null) ? number_format($item['metrics'][$views]) : '—' }}</td><td>{{ is_numeric($likes) ? number_format($likes) : '—' }}</td><td>{{ is_numeric($item['metrics']['comments'] ?? null) ? number_format($item['metrics']['comments']) : '—' }}</td><td>{{ is_numeric($item['metrics']['shares'] ?? null) ? number_format($item['metrics']['shares']) : '—' }}</td><td>{{ is_numeric($item['metrics']['saved'] ?? null) ? number_format($item['metrics']['saved']) : '—' }}</td><td>{{ is_numeric($reach) ? number_format($reach) : '—' }}</td><td>{{ $engagementRate !== null ? number_format($engagementRate, 2).'%' : '—' }}</td></tr>@empty<tr><td colspan="10" class="analytics-empty">No published content was returned for {{ $since }} to {{ $until }}.@if($platform==='instagram' && is_numeric(data_get($data,'account.media_count'))) Instagram reports {{ number_format($data['account']['media_count']) }} media items on the account overall.@endif</td></tr>@endforelse
