@push('scripts')<script>
const searchBox=document.getElementById('post-search'),typeFilter=document.getElementById('type-filter'),csvLink=document.getElementById('csv-export');
function filterPosts(){const q=(searchBox?.value||'').toLowerCase(),t=typeFilter?.value||'';document.querySelectorAll('#posts-table tbody tr[data-kind]').forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(q)||(t&&row.dataset.kind!==t))}
function updateCsv(){const url=new URL(csvLink.href);if(searchBox.value)url.searchParams.set('q',searchBox.value);else url.searchParams.delete('q');if(typeFilter.value)url.searchParams.set('type',typeFilter.value);else url.searchParams.delete('type');csvLink.href=url.toString()}
searchBox?.addEventListener('input',()=>{filterPosts();updateCsv()});typeFilter?.addEventListener('change',()=>{filterPosts();updateCsv()});
document.querySelectorAll('#posts-table th').forEach((th,index)=>th.addEventListener('click',()=>{const body=th.closest('table').tBodies[0],rows=[...body.querySelectorAll('tr[data-kind]')],direction=th.dataset.direction==='asc'?-1:1;th.dataset.direction=direction===1?'asc':'desc';rows.sort((a,b)=>a.cells[index].innerText.localeCompare(b.cells[index].innerText,undefined,{numeric:true})*direction).forEach(row=>body.appendChild(row))}));
</script>@endpush
